import { StoryObj, Meta } from '@storybook/react-webpack5';
import { Provider } from 'react-redux';
import {
  MultichainAccountList,
  type MultichainAccountListProps,
} from './multichain-account-list';
import { AccountGroupId } from '@metamask/account-api';
import { AccountTreeWallets } from '../../../selectors/multichain-accounts/account-tree.types';
import React from 'react';
import mockState from '../../../../test/data/mock-state.json';
import configureStore from '../../../store/store';

const mockSelectedAccountGroup = mockState.metamask
  .selectedAccountGroup as AccountGroupId;

const defaultArgs: MultichainAccountListProps = {
  wallets: mockState.metamask.accountTree
    .wallets as unknown as AccountTreeWallets,
  selectedAccountGroups: [mockSelectedAccountGroup],
};

const store = configureStore({
  metamask: mockState.metamask,
  activeTab: {
    origin: 'https://metamask.github.io',
    protocol: 'https:',
    url: 'https://metamask.github.io/test-dapp/',
  },
});

const meta: Meta<typeof MultichainAccountList> = {
  title: 'Components/MultichainAccounts/MultichainAccountList',
  component: MultichainAccountList,
  parameters: {
    backgrounds: {
      default: 'light',
    },
  },
  decorators: [
    (Story) => (
      <Provider store={store}>
        <Story />
      </Provider>
    ),
  ],
};

export default meta;
type Story = StoryObj<typeof MultichainAccountList>;

export const Default: Story = {
  args: defaultArgs,
};

Default.parameters = {
  docs: {
    description: {
      story:
        'Default state of MultichainAccountList showing various wallets and their accounts.',
    },
  },
};

export const WithCheckboxes: Story = {
  args: {
    ...defaultArgs,
    showAccountCheckbox: true,
  },
};

WithCheckboxes.parameters = {
  docs: {
    description: {
      story:
        'MultichainAccountList with checkboxes enabled for account selection. Checkboxes appear as start accessories on each account row.',
    },
  },
};

export const EditMode: Story = {
  args: {
    ...defaultArgs,
    isEditMode: true,
  },
};

EditMode.parameters = {
  docs: {
    description: {
      story:
        'MultichainAccountList in edit mode. Entropy and other non-private-key wallets show visibility icons, imported private-key wallets show delete icons, account menus are suppressed, and hidden accounts move inline under their own wallet.',
    },
  },
};
